#!/usr/bin/env python3
"""Move the live probe timestamp from the speed panel into the site header."""
from pathlib import Path
import re
root=Path("/var/lib/komari/data/theme/Glassmorphism/dist")
entry=root/"index.html"
if not entry.is_file():
    raise SystemExit("没有找到当前 Glassmorphism 入口，未修改。")
html=entry.read_text(encoding="utf-8")
if "</body>" not in html:
    raise SystemExit("网页入口格式异常，未修改。")
js="(()=>{\n\"use strict\";\nconst PERIOD=3000;\nconst rpcPaths=[\"/rpc2\",\"/api/rpc2\"];\nlet endpoint=rpcPaths[0], seq=0, busy=false, metaById={}, lastMeta=0;\nconst fmt=(raw,suffix=\"\")=>{\n const n=Number(raw);\n if(!Number.isFinite(n))return \"—\";\n let value=Math.abs(n),u=0;\n const units=[\"B\",\"KB\",\"MB\",\"GB\",\"TB\",\"PB\"];\n while(value>=1024&&u<units.length-1){value/=1024;u++;}\n return (n<0?\"-\":\"\")+value.toFixed(2)+\" \"+units[u]+suffix;\n};\nconst formatTime=stamp=>{\n const d=new Date(stamp);\n return isNaN(d.getTime())?\"未知\":d.toLocaleTimeString(\"zh-CN\",{hour12:false});\n};\nfunction updateHeaderDate(stamp){\n  const title=[...document.querySelectorAll(\"div.sticky h3\")].find(\n    el=>/洛杉矶.*VPS.*监控|VPS.*监控/.test(el.textContent||\"\")\n  );\n  if(!title)return;\n  const box=title.parentElement;\n  if(!box)return;\n  box.style.position=\"relative\";\n  let date=box.querySelector(\"[data-fn-header-date]\");\n  if(!date){\n    date=document.createElement(\"span\");\n    date.setAttribute(\"data-fn-header-date\",\"\");\n    date.style.cssText=\"position:absolute;left:40px;top:calc(50% + 7px);max-width:calc(100% - 42px);font-size:10px;line-height:1;font-weight:400;opacity:.65;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;pointer-events:none\";\n    box.appendChild(date);\n    title.style.transform=\"translateY(-5px)\";\n  }\n  const d=new Date(stamp);\n  if(Number.isNaN(d.getTime())){date.textContent=\"\";return;}\n  const pad=n=>String(n).padStart(2,\"0\");\n  date.textContent=d.getFullYear()+\"-\"+pad(d.getMonth()+1)+\"-\"+pad(d.getDate())+\" \"+pad(d.getHours())+\":\"+pad(d.getMinutes())+\":\"+pad(d.getSeconds());\n  date.title=\"最近一次探针上报时间（浏览器本地时间）\";\n}\n\nasync function rpc(method,params={}){\n const body=JSON.stringify({jsonrpc:\"2.0\",id:++seq,method,params});\n let res=await fetch(endpoint,{method:\"POST\",cache:\"no-store\",credentials:\"same-origin\",\n  headers:{\"Content-Type\":\"application/json\"},body});\n if(res.status===404&&endpoint===rpcPaths[0]){\n  endpoint=rpcPaths[1];\n  res=await fetch(endpoint,{method:\"POST\",cache:\"no-store\",credentials:\"same-origin\",\n   headers:{\"Content-Type\":\"application/json\"},body});\n }\n if(!res.ok)throw Error(\"HTTP \"+res.status);\n const obj=await res.json();\n if(obj.error)throw Error(obj.error.message||\"RPC error\");\n if(!obj.result||typeof obj.result!==\"object\")throw Error(\"missing status\");\n return obj.result;\n}\nfunction findCard(name,totalCount){\n const cards=[...document.querySelectorAll(\".node-card\")];\n let card=cards.find(c=>c.getAttribute(\"aria-label\")===(\"查看节点 \"+name+\" 详情\"));\n if(!card&&cards.length===1&&totalCount===1)card=cards[0];\n return card||null;\n}\nfunction updateCard(card,node,status){\n // Anchor to the exact two native traffic-speed <span> elements in NodeCard.vue.\n const speed=[...card.querySelectorAll(\"span\")].filter(el=>{\n   if(el.children.length)return false;\n   return /^-?[\\d,.]+\\s*(?:B|KB|MB|GB|TB|PB)\\/s$/.test(el.textContent.trim());\n });\n if(speed.length<2)return false;\n const speedPanel=speed[0].parentElement?.parentElement;\n const totalsPanel=speedPanel?.nextElementSibling;\n if(!speedPanel||!totalsPanel)return false;\n const totalRows=[...totalsPanel.children].filter(x=>x.tagName===\"DIV\");\n if(totalRows.length<2)return false;\n const upTotal=totalRows[0].querySelector(\"span:last-of-type\");\n const downTotal=totalRows[1].querySelector(\"span:last-of-type\");\n if(!upTotal||!downTotal)return false;\n speed[0].textContent=fmt(status.net_out,\"/s\");\n speed[1].textContent=fmt(status.net_in,\"/s\");\n upTotal.textContent=fmt(status.net_total_up);\n downTotal.textContent=fmt(status.net_total_down);\n\n // The native quota bar remains reactive. Replace only the displayed caption.\n const icon=card.querySelector('[data-node-metric-icon=\"traffic\"]');\n const trafficBlock=icon?.closest(\".flex.flex-col.gap-1\");\n if(trafficBlock){\n   const raw=[...trafficBlock.children].find(el=>\n      el.tagName===\"DIV\" && el.textContent.includes(\"/\") && /(?:B|KB|MB|GB|TB|∞)/.test(el.textContent));\n   if(raw){\n     raw.style.display=\"none\";\n     let label=trafficBlock.querySelector(\"[data-fn-traffic-live]\");\n     if(!label){\n       label=document.createElement(\"div\");\n       label.setAttribute(\"data-fn-traffic-live\",\"\");\n       label.className=\"text-[11px] text-muted-foreground truncate\";\n       raw.after(label);\n     }\n     const a=Number(status.net_total_up)||0,b=Number(status.net_total_down)||0;\n     const typ=node.traffic_limit_type||\"sum\";\n     const used=typ===\"up\"?a:typ===\"down\"?b:typ===\"max\"?Math.max(a,b):typ===\"min\"?Math.min(a,b):a+b;\n     const limit=Number(node.traffic_limit)||0;\n     label.textContent=fmt(used)+\" / \"+(limit>0?fmt(limit):\"∞\");\n   }\n }\n speedPanel.querySelector(\"[data-fn-net-report]\")?.remove();\n updateHeaderDate(status.time);\n speedPanel.title=\"最新探针上报：\"+(status.time||\"未知\")+\"；网页每3秒查询一次\";\n return true;\n}\nasync function tick(){\n if(busy||document.hidden||navigator.onLine===false)return;\n if(location.pathname!==\"/\")return;\n busy=true;\n try{\n  if(!lastMeta||Date.now()-lastMeta>300000){\n   metaById=await rpc(\"common:getNodes\");\n   lastMeta=Date.now();\n  }\n  const statuses=await rpc(\"common:getNodesLatestStatus\");\n  const keys=Object.keys(statuses);\n  for(const [id,st] of Object.entries(statuses)){\n   const info=metaById[id];\n   if(!info)continue;\n   const card=findCard(info.name,keys.length);\n   if(card)updateCard(card,info,st);\n  }\n  document.documentElement.dataset.fnNetLive=\"ok\";\n }catch(e){\n  document.documentElement.dataset.fnNetLive=\"error\";\n  // Do not overwrite native values on transport failure.\n  console.warn(\"[FamilyNet live network]\",e.message||e);\n }finally{busy=false}\n}\nfunction boot(){\n tick();\n setInterval(tick,PERIOD);\n document.addEventListener(\"visibilitychange\",()=>{if(!document.hidden)tick()});\n window.addEventListener(\"online\",tick);\n}\nif(document.readyState===\"loading\")document.addEventListener(\"DOMContentLoaded\",boot,{once:true});\nelse boot();\n})();"
asset=root/"assets/fn-live-network-v2.js"
asset.parent.mkdir(parents=True,exist_ok=True)
asset.write_text(js,encoding="utf-8")
clean=re.sub(r'<script\s+src=["\x27]/assets/fn-live-network-v\d+\.js(?:\?[^"\x27]*)?["\x27]\s+defer></script>',"",html)
clean=clean.replace("</body>",'<script src="/assets/fn-live-network-v2.js?v=20261105b" defer></script></body>',1)
entry.write_text(clean,encoding="utf-8")
print("已移除网速栏下面的上报时间，在顶部“洛杉矶 VPS 监控”标题下显示日期与时间。")
print("保留每3秒实时更新、两位小数、12路 Ping 及原主题其他功能。")
print("请刷新 https://207.57.74.12:9443/?v=date-top-2")
